/** Bulan Indonesia → angka (untuk pengurutan tanggal "Bulan 2025"). */
const BULAN: Record<string, number> = {
  januari: 1, februari: 2, maret: 3, april: 4, mei: 5, juni: 6,
  juli: 7, agustus: 8, september: 9, oktober: 10, november: 11, desember: 12,
};

/** Kunci urut kronologis dari string tanggal (best-effort). */
export function eventDateSort(date: string): number {
  const iso = date.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return Number(iso[1] + iso[2] + iso[3]);
  const m = date.toLowerCase().match(/([a-z]+)\s+(\d{4})/);
  if (m && BULAN[m[1]]) return Number(`${m[2]}${String(BULAN[m[1]]).padStart(2, "0")}00`);
  const y = date.match(/(\d{4})/);
  if (y) return Number(`${y[1]}0000`);
  return 99999999;
}

/** Event dengan angka pengunjung yang masih perkiraan/kapasitas (perlu verifikasi). */
export function eventNeedsVerify(e: GciEvent): boolean {
  return /perkiraan|kapasitas|target|estimasi|terjual/i.test(e.note);
}

export const GCI_EVENTS: GciEvent[] = [...SEED].sort(
  (a, b) => eventDateSort(a.date) - eventDateSort(b.date)
);

export function eventStats(year?: string) {
  const base = year
    ? GCI_EVENTS.filter((e) => (e.date.match(/(20\d{2})/)?.[1] ?? "") === year)
    : GCI_EVENTS;
  return {
    total: base.length,
    musik: base.filter(
      (e) => e.category === "Konser Musik" || e.category === "Festival Musik"
    ).length,
    konser: base.filter((e) => e.category === "Konser Musik").length,
    festival: base.filter((e) => e.category === "Festival Musik").length,
    budaya: base.filter(
      (e) => e.category !== "Konser Musik" && e.category !== "Festival Musik"
    ).length,
    withVisitors: base.filter((e) => e.visitors && !eventNeedsVerify(e)).length,
  };
}
